function slugify(string $title): string
{
    $map = [
        'ą' => 'a', 'ć' => 'c', 'ę' => 'e', 'ł' => 'l', 'ń' => 'n',
        'ó' => 'o', 'ś' => 's', 'ź' => 'z', 'ż' => 'z',
        'Ą' => 'a', 'Ć' => 'c', 'Ę' => 'e', 'Ł' => 'l', 'Ń' => 'n',
        'Ó' => 'o', 'Ś' => 's', 'Ź' => 'z', 'Ż' => 'z',
    ];

    $title = strtr($title, $map);          // 1. transliterate
    $title = strtolower($title);           // 2. lowercase (now ASCII)
    $title = preg_replace('/[^a-z0-9]+/', '-', $title); // 3. collapse
    return trim($title, '-');              // 4. trim edges
}

