function luhn_check(string $number): bool
{
    $number = preg_replace('/[\s-]/', '', $number);
    if (! preg_match('/^[0-9]{2,}$/', $number)) {
        return false;
    }

    $sum = 0;
    $len = strlen($number);
    for ($i = 0; $i < $len; $i++) {
        $d = (int) $number[$i];
        if (($len - $i) % 2 === 0) {   // distance-from-the-right is even → double
            $d *= 2;
            if ($d > 9) {
                $d -= 9;
            }
        }
        $sum += $d;
    }

    return $sum % 10 === 0;
}

function is_valid_isbn10(string $isbn): bool
{
    $isbn = preg_replace('/[\s-]/', '', $isbn);
    if (! preg_match('/^[0-9]{9}[0-9X]$/', $isbn)) {
        return false;
    }

    $sum = 0;
    for ($i = 0; $i < 9; $i++) {
        $sum += (10 - $i) * (int) $isbn[$i];   // weights 10..2
    }
    $sum += $isbn[9] === 'X' ? 10 : (int) $isbn[9];

    return $sum % 11 === 0;
}

