function group_by(array $rows, string $key): array
{
    $groups = [];
    foreach ($rows as $row) {
        $groups[$row[$key]][] = $row;   // keyed by the group value
    }
    return $groups;
}

function flatten(array $items): array
{
    $out = [];
    foreach ($items as $item) {
        if (is_array($item)) {
            array_push($out, ...flatten($item));   // recurse, then spread
        } else {
            $out[] = $item;
        }
    }
    return $out;
}

