function steps(): Generator
{
    echo "  [gen] starting\n";
    yield 1;
    echo "  [gen] middle\n";
    yield 2;
    echo "  [gen] finishing\n";
}

foreach (steps() as $i => $value) {
    echo "  [main] got #{$i} = {$value}\n";
}

