function readRows(string $file): Generator
{
    $handle = fopen($file, 'rb');
    while (($row = fgetcsv($handle)) !== false) {
        yield $row;                 // one row at a time, not the whole file
    }
    fclose($handle);
}

foreach (readRows('huge.csv') as $row) {
    process($row);                  // constant memory for any file size
